/* ======================= SERVICES & BOOT ======================= */
lesson('systemctl', {
  n: 'systemctl', s: 'Controls systemd services: start, stop, restart, enable at boot, and check status.',
  an: 'The control panel of a building\'s facility manager (systemd): switch the elevator, heating or alarm on/off, see their state and whether they come on automatically each morning.',
  nm: '<b>system</b>d <b>c</b>on<b>t</b>ro<b>l</b>.',
  sx: 'systemctl COMMAND [UNIT]   (status | start | stop | restart | reload | enable | disable | is-active | list-units)', p: [['systemctl', 'cmd', 'Client that talks to systemd (PID 1).', true], ['COMMAND', 'arg', 'What to do.', true], ['[UNIT]', 'arg', 'Service name, e.g. nginx or nginx.service.', false]],
  ex1: 'sudo systemctl restart nginx',
  sc: [['connect (D-Bus)', 'connects to systemd\'s private socket / D-Bus', 'connect(3, {sa_family=AF_UNIX, sun_path="/run/systemd/private"}, 32) = 0'], ['sendmsg', 'sends “RestartUnit nginx.service”; polkit checks authorization (needs root)', 'sendmsg(3, {…"RestartUnit"…}, MSG_NOSIGNAL) = 156'], ['(systemd, PID 1)', 'sends SIGTERM to every process in the unit\'s cgroup, waits, then fork()+exec() ExecStart= in a fresh cgroup', ''], ['recvmsg', 'receives the job result', 'recvmsg(3, {…"done"…}, 0) = 120']],
  ch: 'The service\'s processes (and with enable/disable: symlinks in /etc/systemd/system/*.wants/).', out: 'status prints a rich report; start/stop print nothing on success.', ec: 'status: 0 running, 3 not running, 4 no such unit. Others: 0 success, 1 failure.',
  f: [['status', '', 'State, PID, memory, cgroup, recent logs.', 'systemctl status nginx', true], ['start / stop', '', 'Start or stop now.', 'sudo systemctl stop nginx', true], ['restart', '', 'Stop + start.', 'sudo systemctl restart nginx', true], ['reload', '', 'Re-read config without stopping (if supported).', 'sudo systemctl reload nginx', false], ['enable / disable', '', 'Start (or not) automatically at boot.', 'sudo systemctl enable nginx', true], ['--now', '', 'With enable/disable: also start/stop now.', 'sudo systemctl enable --now nginx', false], ['is-active / is-enabled', '', 'Script-friendly checks.', 'systemctl is-active nginx', false], ['list-units --type=service', '', 'All services.', 'systemctl list-units --type=service', false], ['daemon-reload', '', 'Reload unit files after editing them.', 'sudo systemctl daemon-reload', false]],
  e: [['systemctl status nginx', '● nginx.service - A high performance web server…\n     Active: active (running) since …', 'Check a service.'], ['systemctl stop nginx', 'Failed to stop nginx.service: Interactive authentication required.', 'Changing services needs root.'], ['sudo systemctl stop nginx; curl localhost', 'curl: (7) Failed to connect…', 'The web server is gone.'], ['sudo systemctl start nginx; systemctl is-active nginx', 'active', 'Back.'], ['sudo systemctl enable bluetooth', 'Created symlink …', 'Start at boot (not now!).'], ['systemctl list-units --type=service', '', 'Overview.']],
  u: `<p><b>systemd</b> is PID 1: it boots the system and supervises <b>services</b> described by <b>unit files</b> (<code>/usr/lib/systemd/system/nginx.service</code>, overrides in /etc/systemd/system). A unit says how to start (<code>ExecStart=</code>), dependencies (<code>After=</code>, <code>Wants=</code>), restart policy (<code>Restart=on-failure</code>), user, limits…</p><p><b>start ≠ enable:</b> start = run it now; enable = run it automatically at boot (creates a symlink in a target's .wants/ directory). You usually want both: <code>enable --now</code>.</p><p>Each service runs in its own <b>cgroup</b>, so systemd knows ALL its processes and can stop them reliably.</p>`,
  adv: `<p>systemctl talks D-Bus to <code>org.freedesktop.systemd1</code>. Starting queues a <i>job</i>; the unit's processes are spawned via <code>sd-executor</code> into <code>/sys/fs/cgroup/system.slice/nginx.service</code>. Stop sends <code>KillSignal=</code> (SIGTERM) to the cgroup, waits <code>TimeoutStopSec=</code> (90 s), then SIGKILL. Write your own: a [Unit], [Service] with ExecStart, [Install] WantedBy=multi-user.target, then daemon-reload + enable --now.</p>`,
  mi: [['systemctl enable nginx (expecting it to run now)', 'Only takes effect at next boot.', 'sudo systemctl enable --now nginx'], ['Editing a unit file and restarting', 'systemd still uses the old definition.', 'sudo systemctl daemon-reload first'], ['Restarting sshd with a broken config on a remote server', 'You can lock yourself out.', 'sshd -t to test the config first']],
  w: 'Stopping or disabling the wrong service (e.g. <b>ssh</b>, networking, systemd-logind) on a remote machine can cut off your own access. Test configs before restarting (<code>nginx -t</code>, <code>sshd -t</code>) and keep a second session open.',
  r: [['journalctl', 'Read the service\'s logs.'], ['boot', 'Where systemd fits in the boot.'], ['ps', 'ps shows the processes; systemctl shows the service view.'], ['cgroups', 'How systemd tracks processes.']],
  cs: ['<code>systemctl status svc</code>', '<code>sudo systemctl start|stop|restart svc</code>', '<code>enable</code> = at boot · <code>--now</code> = also now', '<code>daemon-reload</code> after editing units', 'Logs: <code>journalctl -u svc</code>'],
  q: [['What does enable do?', ['Starts now', 'Starts automatically at boot', 'Restarts', 'Unmasks'], 1, 'Use --now to also start immediately.'], ['Who actually starts the service process?', ['systemctl', 'systemd (PID 1)', 'bash', 'cron'], 1, 'systemctl only sends a request.'], ['Exit code 3 from systemctl status means…', ['crashed', 'not running', 'not found', 'success'], 1, '0 = running, 3 = inactive.']],
  c: { t: 'Stop the <b>nginx</b> service, confirm with curl that the website is down, then start it again.', try: 'sudo systemctl stop nginx', steps: [['Stop nginx', ctx => !S.services.nginx.active], ['curl localhost fails', ctx => ran(ctx, 'curl') && ctx.line.includes('localhost') && ctx.code !== 0], ['Start nginx again', ctx => S.services.nginx.active && ran(ctx, 'systemctl')]] },
});
lesson('journalctl', {
  n: 'journalctl', s: 'Reads the systemd journal: logs from services, the kernel and the system, with powerful filters.',
  an: 'The building\'s central logbook: every department writes into it, and the clerk can instantly show you “only the elevator entries from today, errors only”.',
  nm: '<b>journal</b> <b>c</b>on<b>t</b>ro<b>l</b>.',
  sx: 'journalctl [-u UNIT] [-p LEVEL] [-n N] [-f] [-b] [--since TIME]', p: [['journalctl', 'cmd', 'The journal reader.', true], ['[FILTERS]', 'opt', '-u unit, -p priority, -b this boot, -k kernel, --since/--until.', false], ['[-n N] [-f]', 'opt', 'Last N lines / follow live.', false]],
  ex1: 'journalctl -u ssh -n 5',
  sc: [['openat /var/log/journal/…', 'opens the binary journal files', 'openat(AT_FDCWD, "/var/log/journal/…/system.journal", O_RDONLY|O_CLOEXEC) = 3'], ['mmap', 'maps them and uses the built-in indexes to find matching entries fast', 'mmap(NULL, 8388608, PROT_READ, MAP_SHARED, 3, 0) = 0x7f…'], ['write', 'prints formatted entries (through less in a terminal)', 'write(1, "Nov 18 09:10:44 linux sshd[2101]: Accepted…", 90) = 90']],
  ch: 'Nothing.', out: 'Log lines: <code>date host process[pid]: message</code>; errors in red.', ec: '0.',
  f: [['-u UNIT', '--unit', 'One service.', 'journalctl -u nginx', true], ['-f', '--follow', 'Follow new entries live.', 'journalctl -u nginx -f', true], ['-n N', '--lines', 'Last N entries.', 'journalctl -n 20', true], ['-p LEVEL', '--priority', 'err, warning, info… (and more severe).', 'journalctl -p err', true], ['-b', '--boot', 'Current boot (-b -1 previous).', 'journalctl -b -1', false], ['-k', '--dmesg', 'Kernel messages.', 'journalctl -k', false], ['--since', '', 'Time filter.', 'journalctl --since "1 hour ago"', false], ['-r', '--reverse', 'Newest first.', 'journalctl -r', false]],
  e: [['journalctl -u ssh -n 5', '… sshd[2110]: Failed password for invalid user admin from 203.0.113.9', 'Recent SSH log — someone is guessing passwords!'], ['journalctl -p err', '', 'Only errors.'], ['journalctl -u nginx', '', 'Everything nginx logged (incl. starts/stops you caused).'], ['journalctl -k | tail -3', '', 'Kernel messages.'], ['journalctl -u mysql -f', '', 'Follow live (Ctrl+C stops).']],
  u: `<p><b>systemd-journald</b> collects stdout/stderr of every service, syslog messages and kernel messages into an indexed binary journal (<code>/var/log/journal/</code> if persistent, otherwise /run). Because entries carry metadata (unit, PID, UID, priority), filtering is fast and precise. Classic text logs (/var/log/syslog, auth.log) may still exist in parallel via rsyslog.</p><p>Priorities: 0 emerg, 1 alert, 2 crit, 3 err, 4 warning, 5 notice, 6 info, 7 debug.</p><p>Members of the <code>adm</code> or <code>systemd-journal</code> group can read all logs; others only their own.</p>`,
  adv: `<p>Each entry has trusted fields set by journald (<code>_PID</code>, <code>_UID</code>, <code>_SYSTEMD_UNIT</code>, <code>_BOOT_ID</code>) — <code>journalctl -o verbose</code> shows them; filter with <code>journalctl _UID=1000</code>. Size limits via <code>/etc/systemd/journald.conf</code> (SystemMaxUse); clean with <code>journalctl --vacuum-time=2weeks</code>. Files are append-only and hash-chained (optionally sealed with FSS).</p>`,
  mi: [['journalctl (no filters)', 'Thousands of lines from the oldest entry.', 'journalctl -u svc -n 50   or -b'], ['Looking in /var/log/nginx for a service crash', 'Startup errors are in the journal.', 'journalctl -u nginx -b'], ['Logs gone after reboot', 'Journal is volatile (in /run) by default on some distros.', 'sudo mkdir /var/log/journal (persistent)']],
  safe: 'Read-only (--vacuum options delete old logs).',
  r: [['systemctl', 'status shows the last few log lines too.'], ['tail', 'tail -f for classic text logs.'], ['grep', 'journalctl -u x | grep pattern.']],
  cs: ['<code>journalctl -u svc</code> one service', '<code>-f</code> follow · <code>-n 50</code> last 50', '<code>-p err</code> errors only', '<code>-b</code> this boot · <code>-k</code> kernel', '<code>--since "1 hour ago"</code>'],
  q: [['Which shows only one service?', ['-s', '-u', '-o', '-x'], 1, '-u UNIT.'], ['What does -p err show?', ['Only info', 'err and more severe', 'Processes', 'Ports'], 1, 'Priority 3 and lower numbers.'], ['Who writes the journal?', ['syslog only', 'systemd-journald', 'the kernel directly', 'each app into /var/log'], 1, 'journald.']],
  c: { t: 'Show the last 3 log lines of the <b>ssh</b> service. Can you spot an attack attempt?', try: 'journalctl -u ssh -n 3', chk: ctx => okRun(ctx, 'journalctl') && ctx.line.includes('ssh') },
});
lesson('boot', {
  n: 'boot process', k: 'systemd-analyze', s: 'What happens from power-on to login: firmware → bootloader → kernel → initramfs → systemd → services.',
  an: 'Opening a shop in the morning: the alarm system checks the building (firmware), the manager unlocks (bootloader), the lights and power come on (kernel), the shift lead (systemd) calls in every department in the right order (services).',
  nm: 'From “pulling yourself up by your own <b>boot</b>straps”.',
  sx: 'systemd-analyze [blame|critical-chain]   ·   dmesg   ·   journalctl -b', p: [['systemd-analyze', 'cmd', 'Boot timing analysis.', true], ['[blame|critical-chain]', 'arg', 'Per-service times / dependency chain.', false]],
  ex1: 'systemd-analyze blame',
  sc: [['(firmware)', 'UEFI runs POST, reads the EFI System Partition and starts the bootloader (shimx64.efi → grubx64.efi)', ''], ['(GRUB)', 'reads /boot/grub/grub.cfg, loads /boot/vmlinuz-* and initrd.img-*, passes the kernel command line', ''], ['(kernel)', 'decompresses, initialises memory, CPUs, drivers; mounts the initramfs as a temporary root; runs /init', ''], ['switch_root + execve(/sbin/init)', 'initramfs finds the real root disk (root=UUID=…), mounts it, and execs systemd as PID 1', 'execve("/sbin/init", ["/sbin/init", "splash"], …)'], ['(systemd)', 'starts units in parallel by dependency until default.target (graphical/multi-user) is reached', '']],
  ch: '—', out: 'systemd-analyze: total time split into firmware, loader, kernel, userspace.', ec: '0.',
  f: [['systemd-analyze', '', 'Total boot time.', 'systemd-analyze', true], ['blame', '', 'Services sorted by start time.', 'systemd-analyze blame', true], ['critical-chain', '', 'The slowest dependency chain.', 'systemd-analyze critical-chain', false], ['dmesg', '', 'Kernel ring buffer (boot messages). Needs root on Ubuntu.', 'sudo dmesg | head', true], ['journalctl -b', '', 'All logs of this boot.', 'journalctl -b -p err', false], ['systemctl get-default', '', 'Target booted into.', 'systemctl get-default', false]],
  e: [['systemd-analyze', 'Startup finished in 3.218s (firmware) + 2.105s (loader) + 1.822s (kernel) + 4.501s (userspace) = 11.646s', 'Where boot time goes.'], ['systemd-analyze blame', '4.012s mysql.service\n1.204s docker.service…', 'Slowest services.'], ['systemd-analyze critical-chain', '', 'What the boot waited on.'], ['sudo dmesg | head -4', '[    0.000000] Linux version 6.8.0-49-generic…', 'First kernel messages.'], ['cat /proc/cmdline', '', '(real Linux) kernel command line from GRUB.']],
  u: `<ol><li><b>Firmware (UEFI/BIOS)</b>: power-on self test, picks a boot device.</li><li><b>Bootloader (GRUB)</b>: menu, loads the <b>kernel</b> (/boot/vmlinuz) and <b>initramfs</b>, passes parameters like <code>root=UUID=… quiet splash</code>.</li><li><b>Kernel</b>: sets up memory, CPUs, drivers; starts the initramfs.</li><li><b>initramfs</b>: a small temporary root filesystem with just enough drivers (disk, RAID, LVM, encryption) to mount the real root, then switches to it.</li><li><b>systemd (PID 1)</b>: mounts filesystems from /etc/fstab, starts services in parallel according to dependencies, reaches the default <b>target</b> (multi-user = text, graphical = desktop).</li></ol><p>Shutdown runs in reverse: systemd stops services, unmounts, then asks the kernel to power off.</p>`,
  adv: `<p>The kernel starts PID 1 from <code>init=</code> (default /sbin/init → systemd) and kernel threads (kthreadd PID 2). Targets replace runlevels (rescue.target ≈ 1, multi-user.target ≈ 3, graphical.target ≈ 5). Emergency recovery: add <code>systemd.unit=rescue.target</code> or <code>init=/bin/bash</code> to the kernel line in GRUB. Kernel messages live in the ring buffer (<code>/dev/kmsg</code>), readable with dmesg (restricted by kernel.dmesg_restrict=1).</p>`,
  mi: [['Editing /boot/grub/grub.cfg directly', 'Overwritten by update-grub.', 'Edit /etc/default/grub then sudo update-grub'], ['A typo in /etc/fstab', 'Boot can drop into emergency mode.', 'Use nofail for optional disks; test with sudo mount -a'], ['dmesg as a normal user on Ubuntu', 'Operation not permitted.', 'sudo dmesg   or   journalctl -k']],
  safe: 'The analysis commands are read-only. (Editing GRUB/fstab can make the system unbootable.)',
  r: [['systemctl', 'Manage the services started at boot.'], ['fstab', 'Which filesystems systemd mounts at boot.'], ['journalctl', 'journalctl -b for boot logs.']],
  cs: ['UEFI → GRUB → kernel → initramfs → systemd', 'systemd = PID 1, starts services in parallel', '<code>systemd-analyze blame</code> slow services', '<code>sudo dmesg</code> / <code>journalctl -k</code>', 'Targets: multi-user / graphical'],
  q: [['What does the initramfs do?', ['Stores user files', 'Temporary root with drivers to mount the real root filesystem', 'Bootloader menu', 'Swap'], 1, 'Then switch_root.'], ['Which process has PID 1?', ['bash', 'systemd (init)', 'kernel', 'GRUB'], 1, 'The first user-space process.'], ['Which shows slowest services at boot?', ['dmesg', 'systemd-analyze blame', 'uptime', 'ps -b'], 1, 'blame.']],
  c: { t: 'Find out how long the last boot took and which service was the slowest.', try: 'systemd-analyze', steps: [['systemd-analyze', ctx => okRun(ctx, 'systemd-analyze') && !ctx.line.includes('blame')], ['systemd-analyze blame', ctx => okRun(ctx, 'systemd-analyze') && ctx.line.includes('blame')]] },
});

/* ======================= SCHEDULING ======================= */
lesson('cron', {
  n: 'cron / crontab', k: 'crontab', s: 'Runs commands automatically on a schedule (every night at 2:00, every 5 minutes…).',
  an: 'An alarm clock with sticky notes: at each matching time it rings and someone carries out the task on the note.',
  nm: 'From Greek <b>chronos</b> (time); <b>crontab</b> = cron table.',
  sx: 'crontab -l | -e | -r | FILE | -    ·    line: MIN HOUR DOM MON DOW COMMAND', p: [['crontab', 'cmd', 'Edit/list your schedule.', true], ['-l / -e / -r', 'opt', 'List / edit / remove your crontab.', false], ['MIN HOUR DOM MON DOW', 'arg', 'Five time fields: minute 0–59, hour 0–23, day of month 1–31, month 1–12, day of week 0–7 (0/7 = Sun).', true], ['COMMAND', 'arg', 'Run with /bin/sh at those times.', true]],
  ex1: 'echo "0 2 * * * /home/user/backup.sh" | crontab -',
  sc: [['(crontab, setgid crontab)', 'validates the syntax and writes your table', 'openat(AT_FDCWD, "/var/spool/cron/crontabs/user", O_WRONLY|O_CREAT|O_TRUNC, 0600) = 3'], ['(cron daemon)', 'wakes up every minute, compares the time with every crontab', 'clock_nanosleep(CLOCK_REALTIME, 0, {tv_sec=60, …}, …)'], ['fork + execve', 'runs matching jobs as their owner via /bin/sh -c', 'execve("/bin/sh", ["/bin/sh", "-c", "/home/user/backup.sh"], …)']],
  ch: 'Your crontab file in /var/spool/cron/crontabs/USER.', out: 'crontab -l prints the table. Job output is mailed to you (if mail is configured) or lost — redirect it!', ec: '0, 1 on syntax errors (“bad minute”).',
  f: [['-l', '', 'List.', 'crontab -l', true], ['-e', '', 'Edit in $EDITOR (validated on save).', 'crontab -e', true], ['-r', '', 'Remove ALL your jobs (no confirmation!).', 'crontab -r', false], ['-', '', 'Install from stdin.', '… | crontab -', false], ['*', '', 'Every value.', '* * * * *', true], ['*/N', '', 'Every N.', '*/5 * * * *', true], ['a,b / a-b', '', 'Lists and ranges.', '0 9-17 * * 1-5', true], ['@reboot @daily @hourly', '', 'Shortcuts.', '@daily /path/job', false]],
  e: [['crontab -l', 'no crontab for user', 'Nothing scheduled yet.'], ['echo "0 2 * * * /home/user/backup.sh" | crontab -', '', 'Every day at 02:00.'], ['(crontab -l; echo "*/15 * * * * /usr/bin/date >> /tmp/ticks.log") | crontab -', '', 'ADD a job, keeping existing ones.'], ['crontab -l', '0 2 * * * /home/user/backup.sh\n*/15 * * * * …', 'Check.'], ['echo "99 * * * * x" | crontab -', '"-":1: bad minute', 'Invalid lines are rejected.'], ['cat /etc/crontab', '', 'System-wide table (has an extra USER column).']],
  u: `<p><b>Reading a schedule</b> (minute hour day-of-month month day-of-week):</p><table><tr><td><code>0 2 * * *</code></td><td>every day 02:00</td></tr><tr><td><code>*/5 * * * *</code></td><td>every 5 minutes</td></tr><tr><td><code>30 8 * * 1-5</code></td><td>weekdays at 08:30</td></tr><tr><td><code>0 0 1 * *</code></td><td>midnight on the 1st of each month</td></tr></table><p><b>Gotchas:</b> cron jobs run with a <b>minimal environment</b> (PATH=/usr/bin:/bin, no aliases, home dir as cwd), so use <b>full paths</b> and redirect output: <code>/home/user/backup.sh &gt;&gt; /home/user/backup.log 2&gt;&amp;1</code>. Times are in the system time zone. Modern systems can also use <b>systemd timers</b>.</p>`,
  adv: `<p>cron (Vixie/cronie) rereads changed crontabs each minute (it checks the spool dir mtime). /usr/bin/crontab is setgid <code>crontab</code> so it can write into the protected spool directory. Access is controlled by /etc/cron.allow / cron.deny. If both DOM and DOW are restricted, the job runs when EITHER matches. systemd timers (<code>OnCalendar=daily</code>, <code>Persistent=true</code>) catch up on missed runs, which cron doesn't.</p>`,
  mi: [['A job works in the terminal but not in cron', 'Different PATH/environment, relative paths.', 'Use absolute paths; set PATH in the crontab; log output'], ['echo "…" | crontab - (to add one job)', 'REPLACES your whole crontab.', '(crontab -l; echo "…") | crontab -'], ['crontab -r (meant -e)', 'Deletes all your jobs immediately — the keys are next to each other!', 'Back up: crontab -l > cron.bak']],
  w: '<b>crontab -r</b> wipes your entire crontab without asking, and <code>… | crontab -</code> replaces it. Keep a backup (<code>crontab -l &gt; ~/cron.bak</code>). Scheduled deletion jobs (find … -delete) run unattended — test them manually first.',
  r: [['at', 'One-time jobs instead of repeating ones.'], ['systemctl', 'systemd timers are the modern alternative.'], ['redir', 'Redirect job output to a log.']],
  cs: ['<code>MIN HOUR DOM MON DOW cmd</code>', '<code>*/5 * * * *</code> every 5 min · <code>0 2 * * *</code> 2am daily', '<code>crontab -l</code> / <code>-e</code>', 'Full paths + <code>>> log 2>&1</code>', '<code>(crontab -l; echo …) | crontab -</code> to add'],
  q: [['What does 30 8 * * 1-5 mean?', ['8:30 every day', '8:30 on weekdays', 'every 30 min from 8', 'Aug 30'], 1, 'Mon–Fri at 08:30.'], ['Why do commands fail in cron but not in your shell?', ['cron is broken', 'Minimal environment / different PATH', 'cron needs sudo', 'Time zone'], 1, 'Use full paths.'], ['Which field comes first?', ['hour', 'minute', 'day', 'month'], 1, 'minute hour dom month dow.']],
  c: { t: '<b>Multi-step:</b> find all <code>.log</code> files larger than 1 MB, compress them, and schedule this to run <b>daily</b> with cron.', try: 'find . -name "*.log" -size +1M', steps: [['Find .log files > 1M (find … -name "*.log" -size +1M)', ctx => ran(ctx, 'find') && /-size\s*\+1M/.test(ctx.line) && ctx.line.includes('.log')], ['Compress them (e.g. -exec gzip {} \\;) → logs/app.log.gz exists', ctx => has('logs/app.log.gz')], ['Install a daily crontab line running find … gzip (e.g. 0 3 * * * find /home/user -name "*.log" -size +1M -exec gzip {} \\;)', ctx => (S.crontab.user || '').split('\n').some(l => /find .*-size .*gzip/.test(l) && /^\s*(\S+\s+\S+\s+\*\s+\*\s+\*|@daily)/.test(l))]] },
});
lesson('at', {
  n: 'at', s: 'Runs a command ONCE at a specific time in the future.',
  an: 'Leaving a note with the night porter: “At 10 pm, switch off the sign.” Done once, then the note is thrown away.',
  nm: '<b>at</b> (a time).',
  sx: 'echo "COMMAND" | at TIME   ·   atq   ·   atrm JOB', p: [['at', 'cmd', 'Queue a one-off job (commands come from stdin).', true], ['TIME', 'arg', 'now + 5 minutes, 14:30, noon, midnight, 10:00 tomorrow…', true], ['atq / atrm', 'cmd', 'List / remove queued jobs.', false]],
  ex1: 'echo "tar czf /tmp/docs.tgz /home/user/docs" | at now + 5 minutes',
  sc: [['read stdin', 'reads the commands', 'read(0, "tar czf /tmp/docs.tgz …\\n", 4096) = 38'], ['openat spool', 'writes a job file capturing your environment and cwd', 'openat(AT_FDCWD, "/var/spool/cron/atjobs/a00001…", O_WRONLY|O_CREAT|O_EXCL, 0700) = 3'], ['(atd)', 'the at daemon runs it with /bin/sh at the given time', '']],
  ch: 'A job file in the at spool; removed after running.', out: '<code>job 1 at Wed Nov 18 09:39:00 2026</code> (on stderr).', ec: '0, 1 on garbled time.',
  f: [['now + N minutes', '', 'Relative time.', 'at now + 10 minutes', true], ['HH:MM', '', 'Next occurrence of that time.', 'at 23:00', true], ['atq', '', 'List pending jobs.', 'atq', true], ['atrm N', '', 'Cancel job N.', 'atrm 1', true], ['-f FILE', '', 'Read commands from a file.', 'at -f job.sh 02:00', false], ['batch', '', 'Run when system load is low.', 'echo cmd | batch', false]],
  e: [['echo "tar czf /tmp/docs.tgz /home/user/docs" | at now + 5 minutes', 'warning: commands will be executed using /bin/sh\njob 1 at …', 'Queue a job.'], ['atq', '1\tWed Nov 18 09:39:00 2026 a user', 'See it.'], ['echo "date >> /tmp/noon.log" | at noon', '', 'At 12:00.'], ['atrm 1; atq', '', 'Cancel.'], ['echo "systemctl restart nginx" | sudo at 03:00', '', 'Maintenance at 3 am (as root).']],
  u: `<p>Use <b>cron</b> for repeating jobs and <b>at</b> for one-time jobs. Unlike cron, at remembers your current directory and most environment variables, so jobs behave more like you'd expect. Output is mailed to you if mail is set up — redirect it to a file to be safe.</p>`,
  adv: `<p>at (from the atd package) stores jobs as shell scripts in /var/spool/cron/atjobs (queue letter a; batch uses b). atd checks the queue and forks <code>/bin/sh</code> for due jobs. Access control: /etc/at.allow / at.deny. systemd alternative: <code>systemd-run --on-active=5m cmd</code>.</p>`,
  mi: [['at now + 5 minutes tar czf …', 'at takes the TIME as arguments and the commands from stdin — here “tar” is read as a time.', 'echo "tar czf …" | at now + 5 minutes'], ['Using at for daily jobs', 'Runs once only.', 'cron'], ['Relying on job output appearing in your terminal', 'Runs detached; output is mailed or lost.', 'Redirect to a log file']],
  safe: 'Only schedules; check atq for what will run.',
  r: [['cron', 'Repeating schedules.'], ['bgamp', 'Run now in the background.'], ['nohup', 'Keep running after logout.']],
  cs: ['<code>echo cmd | at now + 5 minutes</code>', '<code>at 23:00</code> / <code>noon</code> / <code>midnight</code>', '<code>atq</code> list · <code>atrm N</code> cancel', 'One-time (cron = repeating)', 'Commands come from stdin'],
  q: [['at vs cron?', ['Same', 'at = once, cron = repeating', 'at = repeating', 'cron = once'], 1, 'One-off vs schedule.'], ['How are commands given to at?', ['As arguments after the time', 'Via stdin', 'In /etc/at.conf', 'With -c'], 1, 'Pipe or type them.'], ['How do you cancel job 2?', ['at -d 2', 'atrm 2', 'kill %2', 'atq -r 2'], 1, 'atrm.']],
  c: { t: 'Schedule a one-time job 5 minutes from now, then list the queue.', try: 'echo "tar czf /tmp/docs.tgz /home/user/docs" | at now + 5 minutes', steps: [['Queue a job with at', ctx => S.atq.length > 0], ['List with atq', ctx => okRun(ctx, 'atq')]] },
});

/* ======================= LINKS & INODES ======================= */
lesson('ln', {
  n: 'ln (hard link)', k: 'ln', s: 'Creates a hard link: a second name for the SAME file data (same inode).',
  an: 'A person with two names on two door bells: ring either one, the same person answers. Remove one name tag — the person is still there.',
  nm: '<b>l</b>i<b>n</b>k.',
  sx: 'ln [OPTIONS] TARGET [LINK_NAME]', p: [['ln', 'cmd', 'The command (without -s = hard link).', true], ['[OPTIONS]', 'opt', '-f replace existing, -v verbose.', false], ['TARGET', 'arg', 'Existing file.', true], ['[LINK_NAME]', 'arg', 'New name (default: same name in current dir).', false]],
  ex1: 'ln notes.txt notes-hard.txt',
  sc: [['linkat', 'adds a new directory entry pointing to the existing inode; link count +1', 'linkat(AT_FDCWD, "notes.txt", AT_FDCWD, "notes-hard.txt", 0) = 0']],
  ch: 'One more directory entry; the inode\'s link count goes up. No data is copied.', out: 'Nothing (-v prints the link).', ec: '0, 1 on errors (cross-device, directory, exists).',
  f: [['-s', '--symbolic', 'Make a symbolic link instead (see ln -s).', 'ln -s t l', true], ['-f', '--force', 'Replace an existing destination.', 'ln -f a b', false], ['-v', '--verbose', 'Print each link.', 'ln -v a b', false], ['-i', '', 'Ask before replacing.', 'ln -i a b', false]],
  e: [['ln notes.txt notes-hard.txt', '', 'Second name for the same data.'], ['ls -li notes.txt notes-hard.txt', '57 -rw-r--r-- 2 user user … notes.txt\n57 -rw-r--r-- 2 user user … notes-hard.txt', 'Same inode number (57), link count 2.'], ['echo "added" >> notes-hard.txt; tail -1 notes.txt', 'added', 'Change through one name — visible through the other.'], ['rm notes.txt; cat notes-hard.txt', '', 'Data survives: the inode still has one name.'], ['ln docs docs-link', 'ln: docs: hard link not allowed for directory', 'No hard links to directories.']],
  u: `<p>A directory entry is just <b>name → inode number</b>. A hard link adds another entry pointing to the same inode; both names are completely equal — neither is “the original”. The inode's <b>link count</b> (2nd column of ls -l) counts the names. Data is freed only when the count drops to 0 and no process has it open.</p><p><b>Limits:</b> hard links can't cross filesystems (inode numbers are per filesystem) and can't point to directories (that could create loops in the tree).</p>`,
  adv: `<p><code>linkat(2)</code> → <code>vfs_link</code> → filesystem link op: adds a dentry and increments <code>i_nlink</code>, journaled. <code>protected_hardlinks</code> (sysctl) stops users hard-linking files they don't own (prevents tricks against setuid programs). Backup tools (rsync --link-dest, Time Machine-like snapshots) use hard links to store unchanged files only once.</p>`,
  mi: [['ln bigfile /mnt/usb/bigfile', '“Invalid cross-device link”.', 'cp, or ln -s'], ['Expecting rm of one name to delete the data', 'Other names keep it alive.', 'find . -samefile f to locate all names'], ['ln -s vs ln confusion', 'Different semantics.', 'Hard: same inode. Soft: path pointer.']],
  safe: 'ln only adds names. (With -f it replaces an existing name.)',
  r: [['ln-s', 'Symbolic links: can cross filesystems and point to dirs, but break when the target moves.'], ['stat', 'See inode number and link count.'], ['cp', 'A real copy has a NEW inode.']],
  cs: ['<code>ln target newname</code> hard link', 'Same inode, link count +1', 'All names are equal', 'No dirs, no cross-filesystem', 'Data lives until the last name is gone'],
  q: [['After ln a b, how many inodes are there?', ['1', '2', '0', 'depends'], 0, 'One inode, two names.'], ['Can you hard-link across two disks?', ['Yes', 'No', 'With sudo', 'With -f'], 1, 'Inodes are per filesystem.'], ['rm a (after ln a b) — is the data gone?', ['Yes', 'No, b still points to it', 'Half', 'Only metadata'], 1, 'Link count drops to 1.']],
  c: { t: 'Create a hard link <code>notes-hard.txt</code> to a notes file and confirm they share an inode with <code>ls -li</code> or <code>stat</code>.', try: 'ln notes.txt notes-hard.txt', steps: [['Create the hard link', ctx => ctx.events.some(e => e.type === 'link' && e.kind === 'hard')], ['Inspect with ls -li or stat', ctx => (okRun(ctx, 'ls') && /-\w*i/.test(ctx.line)) || okRun(ctx, 'stat')]] },
});
lesson('ln-s', {
  n: 'ln -s (symlink)', k: 'ln', s: 'Creates a symbolic link: a small special file that points to another file or directory by its PATH.',
  an: 'A signpost: “The office has moved → see Building B”. If Building B is demolished, the signpost still stands but leads nowhere.',
  nm: '<b>ln</b> <b>-s</b>ymbolic (also “soft link” or “symlink”).',
  sx: 'ln -s TARGET LINK_NAME', p: [['ln -s', 'cmd', 'Make a symbolic link.', true], ['TARGET', 'arg', 'The path the link will contain (stored as text; doesn\'t have to exist!). Relative targets are relative to the LINK\'s directory.', true], ['LINK_NAME', 'arg', 'Name of the new link.', true]],
  ex1: 'ln -s notes.txt mylink',
  sc: [['symlinkat', 'creates a new inode of type “link” whose content is the target path', 'symlinkat("notes.txt", AT_FDCWD, "mylink") = 0'], ['(on access) readlink', 'when a program opens the link, the kernel reads the stored path and looks that up instead', 'readlinkat(AT_FDCWD, "mylink", "notes.txt", 4096) = 9']],
  ch: 'A new small inode (type l). The target is not touched (its link count doesn\'t change).', out: 'Nothing; ls -l shows <code>mylink -> notes.txt</code> in cyan.', ec: '0, 1 if the link name exists.',
  f: [['-s', '', 'Symbolic.', 'ln -s t l', true], ['-f', '', 'Replace existing link.', 'ln -sf new l', true], ['-n', '', 'Treat an existing link to a dir as a file (with -f to retarget).', 'ln -sfn v2 current', false], ['-r', '', 'Compute a relative target automatically.', 'ln -sr /a/b/f /a/c/l', false], ['readlink', '', '(related) show where a link points.', 'readlink -f mylink', false]],
  e: [['ln -s notes.txt mylink; ls -l mylink', 'lrwxrwxrwx 1 user user 9 … mylink -> notes.txt', 'l type, points to notes.txt.'], ['cat mylink', 'Linux notes…', 'Opening follows the link.'], ['ln -s /var/log logs-sys; ls logs-sys', '', 'Links to directories work.'], ['ln -s missing.txt broken; cat broken', 'cat: broken: No such file or directory', 'Dangling link — target doesn\'t exist.'], ['stat mylink', 'File: mylink -> notes.txt … symbolic link', 'Its own inode, different from notes.txt.']],
  u: `<p>A symlink is its own file (own inode) whose content is just a <b>path string</b>. The kernel follows it on access. Advantages over hard links: can point to <b>directories</b>, can cross <b>filesystems</b>, and you can see where it points. Downside: if the target is moved, renamed or deleted, the link <b>breaks</b> (dangling link).</p><p>Permissions on a symlink are always lrwxrwxrwx and ignored — the TARGET's permissions apply. Common uses: <code>/bin/sh → dash</code>, versioned installs (<code>current → app-2.1</code>), config files in a dotfiles repo.</p>`,
  adv: `<p>Short targets may be stored inline in the inode (“fast symlinks”). Path resolution follows up to 40 links (ELOOP after that). <code>lstat()</code> inspects the link itself, <code>stat()</code> the target. <code>protected_symlinks</code> blocks following symlinks owned by others in sticky world-writable dirs (/tmp attacks). Relative targets resolve against the link's directory, not your cwd — a frequent source of broken links.</p>`,
  mi: [['ln -s ../notes.txt docs/link (from home, thinking relative to cwd)', 'The target is relative to the LINK\'s folder.', 'cd docs && ln -s ../notes.txt link   (or ln -sr)'], ['Deleting the target', 'Link becomes dangling.', 'Update with ln -sfn newtarget link'], ['rm -r linkdir/ (trailing slash)', 'May operate on the TARGET directory\'s contents.', 'rm linkdir (no slash) removes only the link']],
  w: 'Commands applied to a symlink usually affect its <b>target</b>: <code>chmod</code>, writing to it, or <code>rm -r link/</code> with a trailing slash can modify or delete the real data behind it. Remove a link with <code>rm link</code> (no slash).',
  r: [['ln', 'Hard links share the inode.'], ['stat', 'Inspect links vs targets.'], ['ls', 'ls -l shows link -> target.']],
  cs: ['<code>ln -s target linkname</code>', 'Own inode, stores a PATH', 'Works for dirs and across filesystems', 'Breaks if the target moves (dangling)', 'Relative targets: relative to the link\'s folder'],
  q: [['Does a symlink share the target\'s inode?', ['Yes', 'No, it has its own', 'Only for dirs', 'Only on ext4'], 1, 'It stores a path.'], ['What happens when the target is deleted?', ['The link is deleted', 'The link dangles (broken)', 'Data is kept', 'It points to /'], 1, 'Opening fails with ENOENT.'], ['Which can point to a directory?', ['hard link', 'symlink', 'both', 'neither'], 1, 'Symlinks only.']],
  c: { t: 'Create a symlink <code>mylink</code> to <code>fruits.txt</code>, then a <b>broken</b> one named <code>broken</code> pointing to <code>missing.txt</code>.', try: 'ln -s fruits.txt mylink', steps: [['mylink → fruits.txt', ctx => { const r = HP('mylink'); return r.n && lookup('/home/user/mylink', false).n.t === 'l'; }], ['A dangling link “broken”', ctx => { const r = lookup('/home/user/broken', false); return r.n && r.n.t === 'l' && !HP('broken').n; }]] },
});
lesson('stat', {
  n: 'stat', s: 'Shows ALL metadata of a file from its inode: size, blocks, inode number, links, permissions, owner, timestamps.',
  an: 'Pulling the full index card of a library book: catalogue number, shelf, how many copies, who owns it, when it was last changed or borrowed.',
  nm: '<b>stat</b>us (of a file).',
  sx: 'stat [-L] [-c FORMAT] FILE...', p: [['stat', 'cmd', 'The command.', true], ['[-L]', 'opt', 'Follow symlinks (show the target).', false], ['[-c FORMAT]', 'opt', 'Custom output: %a octal mode, %U owner, %s size, %i inode, %h links…', false], ['FILE...', 'arg', 'Files to inspect.', true]],
  ex1: 'stat notes.txt',
  sc: [['statx', 'one system call returns the inode metadata', 'statx(AT_FDCWD, "notes.txt", AT_STATX_SYNC_AS_STAT|AT_SYMLINK_NOFOLLOW, STATX_ALL, {stx_mask=…, stx_size=104, stx_ino=57, stx_nlink=1, stx_mode=S_IFREG|0644, …}) = 0'], ['write', 'formats it', 'write(1, "  File: notes.txt\\n  Size: 104 …", 420) = 420']],
  ch: 'Nothing.', out: 'File, Size, Blocks, IO Block, type, Device, Inode, Links, Access (mode), Uid, Gid, Access/Modify/Change/Birth times.', ec: '0, 1 if a file doesn\'t exist.',
  f: [['-c FMT', '--format', 'Custom output.', "stat -c '%a %U %n' f", true], ['-L', '--dereference', 'Follow symlinks.', 'stat -L link', true], ['-f', '--file-system', 'Filesystem info instead.', 'stat -f /', false], ['-t', '--terse', 'One-line machine-readable.', 'stat -t f', false]],
  e: [['stat notes.txt', '  File: notes.txt\n  Size: 104 … regular file\nDevice: 8,1  Inode: 57  Links: 1\nAccess: (0644/-rw-r--r--) …', 'Everything.'], ["stat -c '%a %A %U %n' notes.txt script.sh", '644 -rw-r--r-- user notes.txt…', 'Custom format.'], ['ln notes.txt n2; stat -c "%i %h %n" notes.txt n2', '57 2 notes.txt\n57 2 n2', 'Same inode, 2 links.'], ['ln -s notes.txt sl; stat sl', 'File: sl -> notes.txt … symbolic link', 'The link itself.'], ['stat docs', '… directory', 'Directories have inodes too.']],
  u: `<p>The <b>inode</b> holds everything about a file except its name and its data: type, permissions, owner/group (as numbers), size, block count, link count, and timestamps. stat shows it all.</p><p><b>Timestamps:</b> <b>Access</b> (atime, last read — often updated lazily, “relatime”), <b>Modify</b> (mtime, content changed), <b>Change</b> (ctime, metadata changed: chmod, chown, rename, link — cannot be set by users), <b>Birth</b> (creation, if the filesystem records it).</p><p><b>Size vs Blocks:</b> Size is the byte length; Blocks are 512-byte units actually allocated (a tiny file still takes a 4 KiB block).</p>`,
  adv: `<p><code>statx(2)</code> (Linux 4.11+) returns struct statx with btime and a mask of valid fields. On ext4 the on-disk <code>ext4_inode</code> is 256 bytes: i_mode, i_uid, i_size, timestamps with nanoseconds, i_links_count, i_blocks, and extent tree for data blocks; <code>debugfs -R "stat &lt;57&gt;" /dev/sda1</code> shows the raw inode.</p>`,
  mi: [['Expecting the file NAME in the inode', 'Names live in directories.', 'ls -i / find -inum to map numbers to names'], ['Using mtime to detect permission changes', 'chmod changes ctime, not mtime.', 'Check Change:'], ['stat on a symlink expecting target info', 'Shows the link.', 'stat -L link']],
  safe: 'Read-only.',
  r: [['ls', 'ls -l shows a subset; ls -i the inode number.'], ['ln', 'Watch link counts change.'], ['touch', 'Change timestamps.']],
  cs: ['<code>stat f</code> full inode info', "<code>stat -c '%a %U %s %n' f</code>", 'Inode = metadata, not the name', 'atime / mtime / ctime / birth', '<code>-L</code> follow symlinks'],
  q: [['Which timestamp changes on chmod?', ['mtime', 'ctime', 'atime', 'birth'], 1, 'ctime = metadata change.'], ['Is the file name stored in the inode?', ['Yes', 'No, in the directory entry', 'Both', 'In /etc/names'], 1, 'Names live in directories.'], ['Which format shows octal permissions?', ['%A', '%a', '%o', '%p'], 1, '%a.']],
  c: { t: 'Display the inode metadata of <code>notes.txt</code> (or notes-old.txt).', try: 'stat notes.txt', chk: ctx => okRun(ctx, 'stat') },
});

/* ======================= DISKS & MOUNTS ======================= */
lesson('mount', {
  n: 'mount', s: 'Attaches a filesystem (disk partition, USB stick, network share…) to a directory in the tree.',
  an: 'Docking a cargo container onto a ship at a labelled bay: once docked, everything inside is reachable through that bay\'s door.',
  nm: '<b>mount</b> (like mounting a drive onto the tree).',
  sx: 'mount [-t TYPE] [-o OPTIONS] DEVICE MOUNTPOINT   |   mount (list)', p: [['mount', 'cmd', 'The command (root to attach).', true], ['[-t TYPE]', 'opt', 'Filesystem type: ext4, vfat, ntfs3, nfs… (usually auto-detected).', false], ['[-o OPTIONS]', 'opt', 'ro, rw, noexec, nosuid, uid=…', false], ['DEVICE', 'arg', '/dev/sdb1, UUID=…, server:/share.', true], ['MOUNTPOINT', 'arg', 'An existing (ideally empty) directory.', true]],
  ex1: 'sudo mount /dev/sdb1 /mnt',
  sc: [['(probe)', 'libblkid reads the partition\'s superblock signature to detect the type', 'read(3, "\\353X\\220mkfs.fat…", 4096) = 4096'], ['mount', 'asks the kernel to attach the filesystem at the directory', 'mount("/dev/sdb1", "/mnt", "vfat", MS_RELATIME, NULL) = 0'], ['(kernel)', 'the vfat driver reads the superblock and root directory; /mnt now shows the device\'s root', '']],
  ch: 'The mount table (/proc/self/mounts). The directory\'s previous content is hidden until umount.', out: 'Nothing on success. Without arguments: the list of mounts.', ec: '0, 32 mount failure.',
  f: [['(no args)', '', 'List mounts.', 'mount | grep sd', true], ['-t TYPE', '', 'Force a type.', 'sudo mount -t vfat /dev/sdb1 /mnt', false], ['-o ro', '', 'Read-only.', 'sudo mount -o ro /dev/sdb1 /mnt', true], ['-o nosuid,noexec', '', 'Safer mounts for untrusted media.', 'sudo mount -o nosuid,noexec …', false], ['-a', '', 'Mount everything in /etc/fstab.', 'sudo mount -a', true], ['--bind', '', 'Mount a directory at another place.', 'sudo mount --bind a b', false]],
  e: [['lsblk', 'sdb\n└─sdb1  14.9G  part', 'Find the USB partition.'], ['ls /mnt', '', 'Empty mount point.'], ['sudo mount /dev/sdb1 /mnt', '', 'Attach it.'], ['ls /mnt', 'music.mp3  photos  README.txt', 'The stick\'s files appear.'], ['mount | grep sdb1', '/dev/sdb1 on /mnt type vfat (rw,relatime)', 'Confirm.'], ['df -h /mnt', '', 'Size of the mounted filesystem.']],
  u: `<p>Linux has <b>one</b> directory tree starting at <code>/</code>. Extra filesystems don't get drive letters; they are <b>mounted</b> on a directory (the mount point). Then paths under it lead into that filesystem. Desktops auto-mount USB sticks under /media/USER/.</p><p>Mount options matter for safety: <code>ro</code> (read-only), <code>nosuid</code> (ignore setuid bits), <code>noexec</code> (no running programs from it), <code>nodev</code>.</p>`,
  adv: `<p>Each mount is a <code>struct mount</code>/<code>vfsmount</code> linking a superblock's root dentry onto a dentry in the parent mount; path lookup crosses mount points transparently. Mount namespaces (containers) give processes different mount tables. The new API uses <code>fsopen/fsmount/move_mount</code>. <code>findmnt</code> shows the tree nicely.</p>`,
  mi: [['mount /dev/sdb /mnt', 'sdb is the whole disk; filesystems live on partitions (sdb1).', 'sudo mount /dev/sdb1 /mnt'], ['Mounting onto a non-empty dir', 'Existing files become invisible (not deleted).', 'Use an empty mount point'], ['Pulling the USB stick without umount', 'Cached writes may be lost → corrupted files.', 'sudo umount /mnt first']],
  w: 'Mounting the <b>wrong device</b> or mounting read-write a disk that\'s in use elsewhere can corrupt data. Mount unknown media with <code>-o ro,nosuid,noexec</code>, and always unmount before unplugging.',
  r: [['umount', 'Detach again.'], ['lsblk', 'Find device names.'], ['fstab', 'Mount automatically at boot.'], ['df', 'Space on mounted filesystems.']],
  cs: ['<code>sudo mount /dev/sdb1 /mnt</code>', '<code>mount</code> list · <code>findmnt</code> tree', 'Partition (sdb1), not disk (sdb)', 'Old content of the dir is hidden', '<code>-o ro,nosuid,noexec</code> for untrusted media'],
  q: [['What happens to files already in /mnt when you mount over it?', ['Deleted', 'Hidden until umount', 'Merged', 'Moved'], 1, 'Covered by the mount.'], ['Which device would you mount?', ['/dev/sdb', '/dev/sdb1', '/dev/usb', 'sdb'], 1, 'A partition with a filesystem.'], ['Who can mount (by default)?', ['anyone', 'root', 'the disk owner', 'group disk'], 1, 'Unless fstab has the user option.']],
  c: { t: 'Mount the USB stick partition <code>/dev/sdb1</code> on <code>/mnt</code> and list its files.', try: 'sudo mount /dev/sdb1 /mnt', steps: [['Mount it', ctx => S.mounts.some(m => m.dev === '/dev/sdb1')], ['ls /mnt shows README.txt', ctx => okRun(ctx, 'ls') && outOf(ctx).includes('README.txt')]] },
});
lesson('umount', {
  n: 'umount', s: 'Detaches a mounted filesystem (after flushing pending writes).',
  an: 'Undocking the container: first everyone must leave it and the last boxes must be loaded, then it can be released.',
  nm: '<b>u</b>n<b>mount</b> (yes, without the first n).',
  sx: 'umount MOUNTPOINT|DEVICE', p: [['umount', 'cmd', 'The command (root).', true], ['MOUNTPOINT|DEVICE', 'arg', '/mnt or /dev/sdb1.', true]],
  ex1: 'sudo umount /mnt',
  sc: [['umount2', 'asks the kernel to detach; fails with EBUSY if anything still uses it', 'umount2("/mnt", 0) = -1 EBUSY (Device or resource busy)'], ['(sync)', 'on success, dirty cached data is written to the device first', '']],
  ch: 'Mount removed; the directory shows its own content again.', out: 'Nothing, or “target is busy”.', ec: '0, 32 failure.',
  f: [['-l', '--lazy', 'Detach now, clean up when no longer busy.', 'sudo umount -l /mnt', true], ['-f', '--force', 'Force (mainly unreachable NFS).', 'sudo umount -f /mnt', false], ['-R', '--recursive', 'Unmount sub-mounts too.', 'sudo umount -R /mnt', false]],
  e: [['cd /mnt; sudo umount /mnt', 'umount: /mnt: target is busy.', 'Your own shell is inside it!'], ['cd ~; sudo umount /mnt', '', 'Works now.'], ['ls /mnt', '', 'Empty again.'], ['lsof /mnt', '', '(when busy) find who uses it.'], ['mount | grep sdb1', '', 'Gone from the mount list.']],
  u: `<p>Linux caches writes in RAM and writes them to disk later. umount <b>flushes</b> that cache — that's why “safely remove” matters for USB sticks. A filesystem is <b>busy</b> while any process has a file open there, or has its current directory inside it (very often: your own shell!). Use <code>lsof /mnt</code> or <code>fuser -vm /mnt</code> to find the culprit.</p>`,
  adv: `<p>umount2 with MNT_DETACH (-l) removes the mount from the namespace immediately and finishes when the last reference is dropped. Busy = the mount's reference count is held by open files, cwd/root of processes, or sub-mounts.</p>`,
  mi: [['unmount /mnt', 'command not found — it\'s umount.', 'sudo umount /mnt'], ['umount while cd\'d into it', 'target is busy.', 'cd ~ first'], ['umount -l then unplug immediately', 'Data may not be flushed yet.', 'sync, wait, then unplug']],
  safe: 'umount refuses while busy; forcing (-f/-l) can lose unsaved data.',
  r: [['mount', 'Attach.'], ['lsof', 'Explain “target is busy”.']],
  cs: ['<code>sudo umount /mnt</code>', 'Flushes cached writes first', '“busy” = open files or a cwd inside', '<code>lsof /mnt</code> find users', 'umount, not unmount'],
  q: [['Most common reason for “target is busy”?', ['Disk full', 'A shell or process is using a file/dir in it', 'Wrong spelling', 'No sudo'], 1, 'Often your own cwd.'], ['Why must you umount before unplugging?', ['Etiquette', 'Cached writes are flushed', 'To save power', 'It doesn\'t matter'], 1, 'Prevents corruption.'], ['Correct spelling?', ['unmount', 'umount', 'unmnt', 'mount -u'], 1, 'umount.']],
  c: { t: 'Unmount <code>/mnt</code> (mount /dev/sdb1 there first if needed). If it\'s busy, find out why.', try: 'sudo umount /mnt', chk: ctx => ran(ctx, 'umount') && ctx.code === 0 && !S.mounts.some(m => m.dev === '/dev/sdb1') },
});
lesson('lsblk', {
  n: 'lsblk', s: 'Lists block devices (disks and partitions) as a tree, with sizes and mount points.',
  an: 'A building plan showing every warehouse (disk), how it\'s divided into rooms (partitions), and which rooms are open to the public (mounted).',
  nm: '<b>l</b>i<b>s</b>t <b>bl</b>oc<b>k</b> devices.',
  sx: 'lsblk [-f] [DEVICE]', p: [['lsblk', 'cmd', 'The command.', true], ['[-f]', 'opt', 'Show filesystem type, label, UUID.', false], ['[DEVICE]', 'arg', 'Only this device.', false]],
  ex1: 'lsblk -f',
  sc: [['openat /sys/block', 'walks sysfs, where the kernel describes every block device', 'openat(AT_FDCWD, "/sys/block", O_RDONLY|O_DIRECTORY) = 3'], ['read /sys/block/sda/size …', 'size, removable flag, partitions', 'read(4, "125829120\\n", 4096) = 10'], ['(udev db / blkid)', 'with -f: filesystem type, label, UUID', '']],
  ch: 'Nothing.', out: 'NAME MAJ:MIN RM SIZE RO TYPE MOUNTPOINTS (or FSTYPE LABEL UUID with -f).', ec: '0.',
  f: [['-f', '--fs', 'Filesystem info (type, UUID).', 'lsblk -f', true], ['-o COLS', '', 'Choose columns.', 'lsblk -o NAME,SIZE,MOUNTPOINT', false], ['-p', '', 'Full device paths.', 'lsblk -p', false], ['-d', '', 'Disks only, no partitions.', 'lsblk -d', false]],
  e: [['lsblk', 'NAME   MAJ:MIN RM   SIZE RO TYPE MOUNTPOINTS\nsda      8:0    0    60G  0 disk\n├─sda1   8:1    0    50G  0 part /…', 'The tree.'], ['lsblk -f', '… sdb1 vfat FAT32 USB_STICK A1B2-C3D4', 'Types and UUIDs (for fstab).'], ['sudo mount /dev/sdb1 /mnt; lsblk', '', 'Mount point appears.'], ['df -h', '', 'Space usage of mounted ones.'], ['cat /etc/fstab', '', 'Which UUIDs mount at boot.']],
  u: `<p>Naming: <code>sda, sdb</code> = SATA/USB disks, <code>nvme0n1</code> = NVMe SSD (partitions nvme0n1p1…), <code>vda</code> = virtual disk, <code>loop</code> = file-backed (snaps), <code>sr0</code> = optical. <b>RM</b> = removable. Names can change between boots (plug order), so configs should use the stable <b>UUID</b> shown by <code>lsblk -f</code>.</p>`,
  adv: `<p>lsblk reads /sys/block and /sys/dev/block plus the udev database (/run/udev/data) for properties like ID_FS_UUID. MAJ:MIN are the device numbers the kernel uses (8 = SCSI disk driver). Partition tables (GPT/MBR) are parsed by the kernel at detection; <code>partprobe</code> rereads them.</p>`,
  mi: [['Using /dev/sdb in fstab', 'The letter may change after reboot → wrong disk mounted.', 'Use UUID=… from lsblk -f'], ['Formatting the wrong disk', 'Data loss.', 'Double-check SIZE and RM columns first'], ['Expecting lsblk to show free space', 'It shows sizes, not usage.', 'df -h']],
  safe: 'Read-only — but it\'s the place to double-check before formatting/partitioning anything.',
  r: [['mount', 'Attach a partition.'], ['df', 'Usage of mounted filesystems.'], ['fstab', 'Use UUIDs from lsblk -f.']],
  cs: ['<code>lsblk</code> disks & partitions tree', '<code>lsblk -f</code> types + UUIDs', 'sda/nvme0n1 = disk, sda1/nvme0n1p1 = partition', 'RM=1 → removable', 'Use UUIDs, not sdX names, in configs'],
  q: [['Which shows UUIDs?', ['lsblk -u', 'lsblk -f', 'lsblk -a', 'lsblk -d'], 1, '-f = filesystem info.'], ['nvme0n1p2 is…', ['a disk', 'partition 2 of an NVMe disk', 'a network card', 'a loop device'], 1, 'p2 = partition 2.'], ['Why prefer UUIDs in /etc/fstab?', ['Shorter', 'Device letters can change between boots', 'Faster', 'Required by ext4'], 1, 'Stable identity.']],
  c: { t: 'Show block devices with their filesystem types and UUIDs.', try: 'lsblk -f', chk: ctx => okRun(ctx, 'lsblk') && ctx.line.includes('-f') },
});
lesson('fstab', {
  n: '/etc/fstab', k: 'cat', s: 'The file that lists which filesystems are mounted where, automatically at boot.',
  an: 'The harbour schedule: which container docks at which bay every morning, with what rules.',
  nm: '<b>f</b>ile <b>s</b>ystem <b>tab</b>le.',
  sx: 'DEVICE  MOUNTPOINT  TYPE  OPTIONS  DUMP  PASS   (one line per filesystem)', p: [['DEVICE', 'arg', 'UUID=…, LABEL=…, /dev/…, server:/share.', true], ['MOUNTPOINT', 'arg', 'Directory (or none for swap).', true], ['TYPE', 'arg', 'ext4, vfat, swap, nfs, auto…', true], ['OPTIONS', 'arg', 'defaults, ro, noatime, nofail, user…', true], ['DUMP PASS', 'arg', 'Backup flag (0) and fsck order (1 = root, 2 = others, 0 = skip).', true]],
  ex1: 'cat /etc/fstab',
  sc: [['(boot) systemd-fstab-generator', 'turns every line into a .mount unit at boot', ''], ['mount (×N)', 'systemd mounts them in dependency order', 'mount("/dev/disk/by-uuid/77b0-12cd", "/boot", "ext4", 0, NULL) = 0'], ['(mount DIR)', 'mount with one argument looks the rest up in fstab', '']],
  ch: 'Editing fstab changes what is mounted at the NEXT boot (or sudo mount -a now).', out: 'cat shows the table.', ec: '—',
  f: [['defaults', '', 'rw, suid, dev, exec, auto, nouser, async.', 'UUID=… /data ext4 defaults 0 2', true], ['nofail', '', 'Don\'t stop the boot if the device is missing.', 'UUID=… /backup ext4 defaults,nofail 0 2', true], ['noatime', '', 'Don\'t update access times (less writes).', '… ext4 defaults,noatime 0 1', false], ['ro', '', 'Read-only.', '', false], ['user / users', '', 'Allow normal users to mount it.', '/dev/sdb1 /media/usb vfat user,noauto 0 0', false], ['noauto', '', 'Don\'t mount at boot.', '', false], ['mount -a', '', 'Mount everything not yet mounted (test your edits!).', 'sudo mount -a', true]],
  e: [['cat /etc/fstab', '# <file system>  <mount point>  <type>  <options>  <dump>  <pass>\nUUID=3f1c-a9e2  /  ext4  errors=remount-ro  0  1…', 'Read the table.'], ['lsblk -f', '', 'Get the UUIDs to use.'], ['grep -v "^#" /etc/fstab', '', 'Without comments.'], ['echo "UUID=A1B2-C3D4 /media/usb vfat defaults,nofail 0 0" | sudo tee -a /etc/fstab', '', 'Add an entry (tee -a, not >).'], ['cat /etc/fstab | tail -1', '', 'Check what you added.']],
  u: `<p>Six fields per line: <b>what</b> (prefer UUID=), <b>where</b>, <b>type</b>, <b>options</b>, <b>dump</b> (0), <b>pass</b> (fsck order: 1 for /, 2 for others, 0 to skip). At boot systemd converts each line into a mount unit. Always <b>test</b> after editing with <code>sudo mount -a</code> (and <code>findmnt --verify</code>) BEFORE rebooting.</p>`,
  adv: `<p>systemd-fstab-generator creates units in /run/systemd/generator/ (e.g. <code>boot.mount</code>); options like <code>x-systemd.automount</code>, <code>x-systemd.device-timeout=10s</code> and <code>_netdev</code> control ordering and on-demand mounting. A failing non-nofail entry drops boot into emergency.target.</p>`,
  mi: [['echo "…" > /etc/fstab', 'Overwrites the whole file → the system won\'t find its root disk at boot!', 'echo "…" | sudo tee -a /etc/fstab'], ['Using /dev/sdb1', 'Device names change.', 'UUID=…'], ['Rebooting without testing', 'A typo can stop the boot.', 'sudo mount -a; findmnt --verify']],
  w: 'A broken <b>/etc/fstab</b> can make the machine <b>fail to boot</b> (emergency mode). Keep a backup (<code>sudo cp /etc/fstab /etc/fstab.bak</code>), append with <code>tee -a</code>, add <code>nofail</code> for removable/optional disks, and test with <code>sudo mount -a</code> before rebooting.',
  r: [['mount', 'Manual mounting; mount -a applies fstab.'], ['lsblk', 'UUIDs for entries.'], ['boot', 'fstab is processed during boot.']],
  cs: ['DEVICE MOUNTPOINT TYPE OPTIONS DUMP PASS', 'Use UUID= from lsblk -f', '<code>nofail</code> for optional disks', 'Append with <code>| sudo tee -a</code>', 'Test: <code>sudo mount -a</code> before reboot'],
  q: [['Which field order is correct?', ['mountpoint device type…', 'device mountpoint type options dump pass', 'type device mountpoint…', 'device type mountpoint…'], 1, 'Six fields.'], ['What does nofail do?', ['Never fails to mount', 'Boot continues if the device is missing', 'Retries forever', 'Read-only'], 1, 'Prevents emergency mode.'], ['How to test fstab changes?', ['reboot', 'sudo mount -a', 'cat /etc/fstab', 'fsck'], 1, 'Mounts all entries now.']],
  c: { t: 'Read <code>/etc/fstab</code> and look up which UUID your USB stick has with <code>lsblk -f</code>.', try: 'cat /etc/fstab', steps: [['cat /etc/fstab', ctx => okRun(ctx, 'cat') && ctx.line.includes('/etc/fstab')], ['lsblk -f', ctx => okRun(ctx, 'lsblk') && ctx.line.includes('-f')]] },
});
